using NovaHarvest.Core.Dialogue;
namespace NovaHarvest.Core.NPC.Characters; public static class LyraDialogue { public static Dialogue FirstEncounter() { var d = new Dialogue("dialogue_lyra_first_encounter", "start"); var s = new DialogueNode("start", "Lyra", "Você... também caiu aqui?"); s.AddChoice(new DialogueChoice("yes", "Sim. Minha nave foi destruída.", "ship_destroyed", 5)); s.AddChoice(new DialogueChoice("escape", "Estou procurando uma forma de sair daqui.", "escape", 2)); s.AddChoice(new DialogueChoice("silence", "Não quero falar sobre isso.", "silence", -2)); d.AddNode(s); var a = new DialogueNode("ship_destroyed", "Lyra", "Então você entende. Minha cápsula foi danificada durante a queda. Achei que estava sozinha neste planeta."); a.SetNextNode("plant_warning"); d.AddNode(a); var b = new DialogueNode("escape", "Lyra", "Se encontrar uma forma de sair daqui, me avise. Minha pesquisa pode ser importante para consertar sua nave."); b.SetNextNode("plant_warning"); d.AddNode(b); var c = new DialogueNode("silence", "Lyra", "Tudo bem. Eu também não gosto de falar sobre a queda."); c.SetNextNode("plant_warning"); d.AddNode(c); var w = new DialogueNode("plant_warning", "Lyra", "Mas antes de qualquer coisa... não toque naquela planta."); w.SetNextNode("plant_joke"); d.AddNode(w); d.AddNode(new DialogueNode("plant_joke", "Lyra", "Ela tentou me comer há menos de uma hora.")); return d; } }
